"""Original substance-use questions: alcohol withdrawal and continuing care."""
from qbank_authoring import question,ref
rows=[]
AW=ref('ASAM alcohol withdrawal management guideline','https://www.asam.org/quality-care/clinical-guidelines/alcohol-withdrawal-management-guideline')
AU=ref('NICE alcohol-use disorder management','https://www.nice.org.uk/guidance/cg115/chapter/Recommendations')
OU=ref('SAMHSA TIP 63: medications for opioid-use disorder','https://www.samhsa.gov/resource/ebp/tip-63-medications-opioid-use-disorder')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A heavy daily drinker develops tremor, sweating, anxiety and tachycardia 12 hours after abruptly reducing intake. Which mechanism is most likely?', 'Alcohol withdrawal from neuroadaptation to chronic depressant exposure',[
 ('Acute ethanol intoxication as the most typical explanation','The reduction and hyperadrenergic pattern favor withdrawal.'),('Opioid intoxication','That more often causes respiratory depression and reduced consciousness.'),('Nicotine withdrawal as a sufficient explanation for the whole syndrome','It does not usually explain this risk pattern and degree of alcohol-related autonomic activation.')],
 'Withdrawal follows a change in exposure, not only a zero blood level','**Chronic alcohol exposure produces inhibitory/excitatory adaptations.**',['A reduction can unmask CNS hyperexcitability.','Withdrawal can begin while alcohol remains measurable.'],'**Assess severity and risk of complicated withdrawal.**',['Review prior seizures/delirium, comorbidity and concurrent sedatives.','Treat other causes of tachycardia and tremor when indicated.'],[['Trigger','Abrupt reduction'],['Physiology','Hyperexcitability'],['Assessment','Current severity plus future risk']],[AW],style='clinical_scenario')

q('A patient develops a generalized seizure 20 hours after stopping heavy alcohol use and is then alert. Which statement is correct?', 'Alcohol withdrawal seizure is possible, but other seizure causes and complications still require assessment',[
 ('The seizure proves delirium tremens despite intact attention','Delirium requires a disturbance of attention/awareness, not seizure alone.'),('A history of alcohol use removes the need to consider head injury or metabolic causes','These can coexist and may be dangerous.'),('Phenytoin alone is the standard prevention treatment for uncomplicated withdrawal seizures','Benzodiazepine-based withdrawal treatment addresses the mechanism; phenytoin is not effective for withdrawal alone.')],
 'Do not turn a plausible cause into diagnostic closure','**Withdrawal seizures often occur early after a marked reduction in drinking.**',['Assess glucose, electrolytes, trauma and focal or atypical features.','A seizure increases concern for further complicated withdrawal.'],'**Provide indicated acute seizure and withdrawal treatment with monitoring.**',['Use a suitable monitored setting.','Treat a separate epilepsy disorder if present rather than assuming every seizure is withdrawal.'],[['Timing','Often within 6–48 h'],['Alert afterward','Not automatically DT'],['Treatment','Withdrawal-directed benzodiazepine strategy']],[AW],style='clinical_scenario')

q('Three days after stopping heavy alcohol use, a patient has fluctuating attention, disorientation, visual hallucinations, agitation and marked autonomic activation. Which diagnosis is most likely?', 'Alcohol withdrawal delirium',[
 ('Alcoholic hallucinosis with a clear sensorium','The disturbed attention and disorientation indicate delirium.'),('Uncomplicated anxiety','The cognitive fluctuation and severe autonomic syndrome go beyond anxiety.'),('Primary schizophrenia established by visual hallucinations alone','The acute withdrawal context and delirium pattern require medical treatment.')],
 'Delirium changes both urgency and monitoring','**Withdrawal delirium combines cognitive disturbance with severe withdrawal physiology.**',['Timing varies and should not be used as an inflexible exclusion rule.','Infection, trauma and metabolic disease can contribute.'],'**Use intensive monitored withdrawal treatment and supportive care.**',['Protect airway, hydration, electrolytes and temperature.','Do not rely on an antipsychotic alone to prevent withdrawal seizures.'],[['Attention','Fluctuating/impaired'],['Autonomic state','Often markedly activated'],['Care','High-acuity monitored treatment']],[AW],style='clinical_scenario')

q('Which medication class is first-line for preventing and treating severe alcohol-withdrawal seizures and delirium?', 'Benzodiazepines',[
 ('Antipsychotics as sole treatment','They may have selected adjunctive roles but do not adequately treat the withdrawal mechanism.'),('Beta blockers as sole treatment','They may blunt autonomic signs without preventing the major CNS complications.'),('Phenytoin for every patient regardless of a separate seizure disorder','It does not effectively treat alcohol withdrawal itself.')],
 'Treat the CNS hyperexcitability rather than masking its signs','**Benzodiazepines provide cross-tolerant GABAergic treatment.**',['Regimen and setting depend on severity and monitoring capacity.','Phenobarbital has selected protocolized roles with experienced clinicians.'],'**Monitor sedation, breathing and clinical response.**',['Use caution with concurrent opioids and other sedatives.','Continue thiamine and medical supportive care.'],[['Core treatment','Benzodiazepine pathway'],['Autonomic agents','Not sufficient alone'],['Antipsychotics','Selected adjunct, not sole protection']],[AW])

q('A patient needs benzodiazepine treatment for alcohol withdrawal and has advanced liver dysfunction. Which agent among these is often favored because it avoids long-lived oxidative metabolites?', 'Lorazepam',[
 ('Diazepam','Its active metabolites can accumulate with impaired oxidative metabolism.'),('Chlordiazepoxide','It also has long-lived metabolites and can accumulate.'),('Clonazepam selected solely because all long-acting drugs are safer in cirrhosis','Long duration alone does not confer that safety advantage.')],
 'Match pharmacokinetics to organ function','**Lorazepam relies mainly on glucuronidation rather than the same oxidative pathway as diazepam.**',['No sedative is risk-free in severe liver disease.','Distinguish withdrawal from hepatic encephalopathy and mixed states.'],'**Use a monitored, response-guided regimen.**',['Assess breathing and oversedation frequently.','Treat the underlying liver and medical problems concurrently.'],[['Lorazepam','No long-lived oxidative metabolites'],['Diazepam/chlordiazepoxide','Potential accumulation'],['Monitoring','Still essential']],[AW],style='clinical_scenario')

q('Why is CIWA-Ar unsuitable as the sole titration tool in an intubated or delirious withdrawal patient?', 'Several items require reliable patient reporting and can be confounded by other illness',[
 ('It directly measures serum ethanol and is therefore too invasive','It is a clinical symptom scale, not a drug assay.'),('A high score specifically proves alcohol withdrawal regardless of context','Other illnesses can raise the score.'),('It replaces clinical examination in every ICU protocol','It does not replace an appropriate objective/clinical assessment.')],
 'A scale must fit the patient’s ability to participate','**Subjective symptom items lose validity when communication or attention is impaired.**',['Use a suitable objective ICU/withdrawal monitoring approach.','Pain, sepsis, delirium and other causes can overlap.'],'**Treat the clinical syndrome with an appropriate protocol.**',['Do not give escalating sedative solely to correct a confounded number.','Reassess the diagnosis and airway safety.'],[['CIWA-Ar','Requires participation'],['Delirium/intubation','Limits validity'],['Alternative','Objective monitored clinical approach']],[AW])

q('A malnourished alcohol-dependent patient has confusion, gait ataxia and an ocular-motor abnormality. Which treatment should be started promptly?', 'Parenteral thiamine for suspected Wernicke encephalopathy',[
 ('Wait for the full classic triad in every case before treatment','The triad is often incomplete and delay risks irreversible injury.'),('Oral folate alone as the specific treatment','This does not replace thiamine in suspected Wernicke disease.'),('Treat only withdrawal with benzodiazepines','Sedation does not correct thiamine deficiency.')],
 'Wernicke encephalopathy is a clinical treatment emergency','**Thiamine deficiency compromises cerebral energy metabolism.**',['Use a therapeutic parenteral regimen for suspected disease, not merely a routine low-dose prophylactic schedule.','Magnesium deficiency can impair response.'],'**Treat promptly and evaluate other causes of confusion.**',['Do not wait for a confirmatory thiamine test or MRI.','Provide nutrition and ongoing replacement with specialist guidance.'],[['Risk','Malnutrition/alcohol dependence'],['Signs','Cognitive, gait or ocular abnormalities'],['Action','Prompt therapeutic parenteral thiamine']],[AW,ref('UK alcohol treatment guideline: pharmacological interventions','https://www.gov.uk/guidance/clinical-guidelines-for-alcohol-treatment/10-pharmacological-interventions')],style='clinical_scenario')

q('An alcohol-dependent malnourished patient is unconscious with glucose 32 mg/dL. Thiamine is being prepared. Which sequence is appropriate?', 'Treat hypoglycemia immediately and give parenteral thiamine promptly, concurrently when feasible',[
 ('Withhold glucose until thiamine becomes available regardless of delay','Profound hypoglycemia requires immediate treatment.'),('Give glucose and omit thiamine because the patient wakes up','Thiamine deficiency risk remains.'),('Give only saline and wait for spontaneous glucose recovery','This does not treat the demonstrated emergency.')],
 'Do not trade one preventable brain injury for another','**Urgent glucose correction must not be delayed.**',['Thiamine should be provided promptly in the at-risk patient.','Both interventions can be administered concurrently.'],'**Continue assessment after consciousness improves.**',['Check for recurrent hypoglycemia and other causes.','Provide nutrition, electrolyte and withdrawal care as appropriate.'],[['Immediate danger','Hypoglycemia'],['Treatment','Glucose without delay'],['Parallel need','Prompt parenteral thiamine']],[AW],style='clinical_scenario')

q('Which alcohol-use-disorder medication can precipitate opioid withdrawal and block opioid analgesia?', 'Naltrexone',[
 ('Acamprosate','It does not act as an opioid receptor antagonist.'),('Disulfiram','It inhibits aldehyde dehydrogenase rather than opioid receptors.'),('Thiamine','It is vitamin replacement, not an opioid antagonist.')],
 'Alcohol treatment selection includes other drug exposure','**Naltrexone antagonizes opioid receptors.**',['Assess current opioid use and planned analgesia before initiation.','Review liver status and the product’s contraindications.'],'**Combine medication with an ongoing recovery plan.**',['Discuss the patient’s goals and expected effect.','Do not use it as a substitute for acute alcohol-withdrawal treatment.'],[['Naltrexone','Opioid antagonism'],['Acamprosate','Different relapse-prevention mechanism'],['Disulfiram','Aldehyde dehydrogenase inhibition']],[AU,OU])

q('Which organ-function issue is particularly important when considering acamprosate?', 'Renal impairment, because the drug is renally eliminated and severe impairment can contraindicate use',[
 ('An assumption that hepatic metabolism requires the same precautions as disulfiram','Acamprosate is not substantially hepatically metabolized.'),('A requirement to induce opioid withdrawal before every dose','It is not an opioid antagonist.'),('Routine ECG evidence of sodium-channel blockade','This is not the principal acamprosate safety issue.')],
 'Relapse-prevention agents have different safety profiles','**Acamprosate can be useful after withdrawal for abstinence-oriented treatment.**',['Kidney function determines suitability and dosing.','Adherence to the dosing schedule affects real-world benefit.'],'**Use it with psychological and social support.**',['Review ongoing benefit and tolerability.','Do not expect it to treat acute withdrawal or intoxication.'],[['Elimination','Renal'],['Use','Relapse prevention after withdrawal'],['Safety','Renal-function review']],[AU])

q('What is essential before using disulfiram for alcohol-use disorder?', 'Informed agreement, understanding of the alcohol–disulfiram reaction and assessment of medical suitability',[
 ('Covert administration by relatives to enforce abstinence','This is unsafe and violates informed treatment principles.'),('Using it as a benzodiazepine substitute for acute severe withdrawal','It does not treat withdrawal hyperexcitability.'),('Assuming alcohol-containing medicines cannot trigger problems','Patients need advice about relevant alcohol exposure sources.')],
 'An aversive medication requires informed participation','**Aldehyde dehydrogenase inhibition can cause a dangerous reaction after alcohol exposure.**',['Assess liver and cardiovascular risks and contraindications.','Supervision may support adherence when agreed.'],'**Use a clear safety and follow-up plan.**',['Explain that the reaction risk can persist after stopping.','Combine with psychosocial treatment rather than relying on aversion alone.'],[['Mechanism','Acetaldehyde accumulation'],['Requirement','Informed agreement'],['Monitoring','Medical suitability and adherence']],[AU])

q('A patient completes alcohol withdrawal without complications. Which next step best reduces the chance that detoxification becomes an isolated repeated event?', 'Link directly to continuing treatment addressing relapse prevention, goals, comorbidity and social needs',[
 ('Discharge with no follow-up because withdrawal is resolved','Withdrawal management is not the whole treatment of alcohol-use disorder.'),('Continue sedative withdrawal medication indefinitely as the default recovery plan','This can create additional dependence and harm.'),('Assume recurrence reflects lack of willpower rather than reassessing care','Relapse risk is multifactorial and treatment can be adapted.')],
 'Detoxification and recovery are different care phases','**An effective pathway connects acute stabilization to ongoing support.**',['Consider relapse-prevention medication when suitable.','Address housing, relationships, nutrition, liver disease and coexisting mental illness.'],'**Agree a realistic shared plan and arrange follow-up.**',['Offer evidence-based psychological interventions.','Use nonjudgmental reassessment if drinking recurs.'],[['Acute phase','Safe withdrawal'],['Continuing phase','Relapse prevention and recovery'],['Support','Medical, psychological and social']],[AW,AU],style='clinical_scenario')
